css:
.aph-vt { font-family: "Times New Roman", Times, serif; font-size: 12.5px; color: #000; line-height: 1.35; }
.aph-vt table { width: 100%; border-collapse: collapse; font-size: inherit; }
.aph-vt .aph-head td, .aph-vt .aph-title td, .aph-vt .aph-sign td { border: 0; vertical-align: top; padding: 0; }
.aph-vt .aph-mau { width: 42%; text-align: center; font-size: 11.5px; }
.aph-vt .aph-title td { padding: 8px 0 4px; }
.aph-vt .aph-side { width: 24%; }
.aph-vt .aph-center { text-align: center; }
.aph-vt .aph-name { font-size: 17px; font-weight: bold; letter-spacing: 0.5px; }
.aph-vt .aph-date { font-style: italic; }
.aph-vt .aph-noco { padding-top: 22px !important; padding-left: 12px !important; }
.aph-vt .aph-info { margin: 4px 0 6px; line-height: 1.6; }
.aph-vt .aph-sec { font-weight: bold; margin: 10px 0 4px; }
.aph-vt .aph-tbl th, .aph-vt .aph-tbl td { border: 1px solid #000; padding: 3px 4px; }
.aph-vt .aph-tbl th { text-align: center; font-weight: bold; vertical-align: middle; }
.aph-vt .aph-tbl .aph-letter td { text-align: center; font-weight: bold; padding: 1px; }
.aph-vt .aph-tbl .c { text-align: center; }
.aph-vt .aph-tbl .r { text-align: right; white-space: nowrap; }
.aph-vt .aph-tbl small { font-size: 10.5px; }
.aph-vt .c-stt { width: 5%; }
.aph-vt .c-ma { width: 14%; }
.aph-vt .c-dvt { width: 7%; }
.aph-vt .c-sl { width: 10%; }
.aph-vt .c-tien { width: 12%; }
.aph-vt .aph-sign-date { text-align: right; font-style: italic; margin-top: 10px; padding-right: 4%; }
.aph-vt .aph-sign td { text-align: center; padding-top: 4px; }
.aph-vt .aph-sign-name { margin-top: 70px; }

html:
{#- Phiếu kho cho Stock Entry, chọn mẫu theo mục đích phiếu:
    nhận thừa/nhập khác -> Phiếu nhập kho (01-VT); xuất, chuyển kho -> Phiếu xuất kho (02-VT);
    sản xuất, đóng gói -> Phiếu sản xuất (xuất dùng + nhập kho). Ẩn giá theo aphvh_an_gia. -#}
{%- set an = aphvh_an_gia(doc) -%}
{%- set nc = aphvh_no_co(doc) -%}
{%- set cty = aphvh_cong_ty(doc.company) -%}
{%- set p = doc.purpose -%}
{%- set ra = doc.items | selectattr("s_warehouse") | list -%}
{%- set vao = doc.items | selectattr("t_warehouse") | list -%}
{%- if p in ("Repack", "Manufacture", "Disassemble") -%}
  {%- set kieu, mau, tieu_de = "sx", "", "PHIẾU SẢN XUẤT" -%}
{%- elif p in ("Material Receipt",) -%}
  {%- set kieu, mau, tieu_de = "nhap", "01 - VT", "PHIẾU NHẬP KHO" -%}
{%- else -%}
  {%- set kieu, mau, tieu_de = "xuat", "02 - VT", "PHIẾU XUẤT KHO" -%}
{%- endif -%}

{%- macro bang(rows, loai, an) -%}
<table class="aph-tbl">
  <thead>
    <tr>
      <th rowspan="2" class="c-stt">STT</th>
      <th rowspan="2">Tên, nhãn hiệu, quy cách, phẩm chất vật tư, dụng cụ, sản phẩm, hàng hóa</th>
      <th rowspan="2" class="c-ma">Mã số</th>
      <th rowspan="2" class="c-dvt">Đơn vị tính</th>
      <th colspan="2">Số lượng</th>
      <th rowspan="2" class="c-tien">Đơn giá</th>
      <th rowspan="2" class="c-tien">Thành tiền</th>
    </tr>
    <tr>
      <th class="c-sl">{{ "Theo chứng từ" if loai == "nhap" else "Yêu cầu" }}</th>
      <th class="c-sl">{{ "Thực nhập" if loai == "nhap" else "Thực xuất" }}</th>
    </tr>
    <tr class="aph-letter"><td>A</td><td>B</td><td>C</td><td>D</td><td>1</td><td>2</td><td>3</td><td>4</td></tr>
  </thead>
  <tbody>
  {%- set ns = namespace(tong=0) %}
  {%- for row in rows %}
    {%- set ns.tong = ns.tong + (row.amount or 0) %}
    <tr>
      <td class="c">{{ loop.index }}</td>
      <td>{{ row.item_name }}
        {%- if loai == "nhap" and row.aphvh_kg and row.uom != "Kg" %}<br><small>{{ aphvh_so(row.aphvh_kg) }} kg</small>{% endif %}
        {%- if row.batch_no %}<br><small>Lô: {{ row.batch_no }}</small>{% endif %}
        {%- if row.get("lo_nhap_khau") %}<br><small>Lô nhập khẩu: {{ row.lo_nhap_khau }}</small>{% endif %}
        {%- if loai == "xuat" and row.t_warehouse %}<br><small>Sang kho: {{ aphvh_ten_kho(row.t_warehouse) }}</small>{% endif %}</td>
      <td class="c">{{ row.item_code }}</td>
      <td class="c">{{ row.uom }}</td>
      <td></td>
      <td class="r">{{ aphvh_so(row.qty) }}</td>
      <td class="r">{{ "" if an else aphvh_so(row.valuation_rate, 0) }}</td>
      <td class="r">{{ "" if an else aphvh_so(row.amount, 0) }}</td>
    </tr>
  {%- endfor %}
    <tr>
      <td></td><td class="c"><b>Cộng</b></td><td></td><td></td><td></td><td></td><td></td>
      <td class="r"><b>{{ "" if an else aphvh_so(ns.tong, 0) }}</b></td>
    </tr>
  </tbody>
</table>
{%- if not an %}
<div class="aph-info"><div>- Tổng số tiền (viết bằng chữ): {{ aphvh_bang_chu(ns.tong) }}</div></div>
{%- endif %}
{%- endmacro -%}

{%- macro ten_kho(rows, field) -%}
{%- for k in rows | map(attribute=field) | select | unique | list %}{{ aphvh_ten_kho(k) }}{% if not loop.last %}, {% endif %}{% endfor -%}
{%- endmacro -%}

<div class="aph-vt">
<table class="aph-head"><tr>
  <td><b>Đơn vị:</b> {{ cty.ten }}{% if cty.dia_chi %}<br><b>Địa chỉ:</b> {{ cty.dia_chi }}{% endif %}</td>
  <td class="aph-mau">{% if mau %}<b>Mẫu số {{ mau }}</b><br><i>(Ban hành theo Thông tư số 133/2016/TT-BTC<br>ngày 26/08/2016 của Bộ Tài chính)</i>{% endif %}</td>
</tr></table>
<table class="aph-title"><tr>
  <td class="aph-side"></td>
  <td class="aph-center">
    <div class="aph-name">{{ tieu_de }}</div>
    <div class="aph-date">{{ aphvh_ngay(doc.posting_date) }}</div>
    <div>Số: {{ doc.name }}</div>
  </td>
  <td class="aph-side aph-noco">Nợ: {{ nc.no }}<br>Có: {{ nc.co }}</td>
</tr></table>

{%- if kieu == "nhap" %}
<div class="aph-info">
  <div>- Họ và tên người giao: ..............................</div>
  <div>- Theo: {{ doc.stock_entry_type }}{% if doc.remarks %} — {{ doc.remarks }}{% endif %}</div>
  <div>- Nhập tại kho: {{ ten_kho(vao, "t_warehouse") }}</div>
</div>
{{ bang(vao, "nhap", an) }}
{%- elif kieu == "xuat" %}
<div class="aph-info">
  <div>- Họ và tên người nhận hàng: ..............................  Địa chỉ (bộ phận): ..............................</div>
  <div>- Lý do xuất kho: {{ doc.stock_entry_type }}{% if doc.remarks %} — {{ doc.remarks }}{% endif %}</div>
  <div>- Xuất tại kho: {{ ten_kho(ra, "s_warehouse") }}{% if vao %}. Nhập tại kho: {{ ten_kho(vao, "t_warehouse") }}{% endif %}</div>
</div>
{{ bang(ra, "xuat", an) }}
{%- else %}
<div class="aph-info">
  <div>- Loại phiếu: {{ doc.stock_entry_type }}{% if doc.remarks %} — {{ doc.remarks }}{% endif %}</div>
  <div>- Xuất tại kho: {{ ten_kho(ra, "s_warehouse") }}. Nhập tại kho: {{ ten_kho(vao, "t_warehouse") }}</div>
</div>
<div class="aph-sec">I. Nguyên liệu, bao bì xuất dùng</div>
{{ bang(ra, "xuat", an) }}
<div class="aph-sec">II. Thành phẩm, phụ phẩm nhập kho</div>
{{ bang(vao, "nhap", an) }}
{%- endif %}

<div class="aph-sign-date">{{ aphvh_ngay(doc.posting_date) }}</div>
<table class="aph-sign"><tr>
  <td><b>Người lập phiếu</b><br><i>(Ký, họ tên)</i><div class="aph-sign-name">{{ aphvh_ten_nguoi(doc.owner) }}</div></td>
  {%- if kieu == "nhap" %}
  <td><b>Người giao hàng</b><br><i>(Ký, họ tên)</i></td>
  <td><b>Thủ kho</b><br><i>(Ký, họ tên)</i></td>
  <td><b>Kế toán trưởng</b><br><i>(Hoặc bộ phận có nhu cầu nhập)<br>(Ký, họ tên)</i></td>
  {%- elif kieu == "xuat" %}
  <td><b>Người nhận hàng</b><br><i>(Ký, họ tên)</i></td>
  <td><b>Thủ kho</b><br><i>(Ký, họ tên)</i></td>
  <td><b>Kế toán trưởng</b><br><i>(Hoặc bộ phận có nhu cầu nhập)<br>(Ký, họ tên)</i></td>
  <td><b>Giám đốc</b><br><i>(Ký, họ tên)</i></td>
  {%- else %}
  <td><b>Tổ trưởng sản xuất</b><br><i>(Ký, họ tên)</i></td>
  <td><b>Thủ kho</b><br><i>(Ký, họ tên)</i></td>
  <td><b>Kế toán trưởng</b><br><i>(Ký, họ tên)</i></td>
  {%- endif %}
</tr></table>
</div>
